import java.util.*;

public class Main {
    static final String[] LEVELS = {"DEBUG", "INFO", "WARN", "ERROR"};

    // Each handler has its own minimum level (chain of handlers)
    static class Handler {
        String name; int min;
        Handler(String n, int m) { name = n; min = m; }
        void handle(int level, String text) {
            if (level >= min) System.out.println("  " + name + " <- " + LEVELS[level] + " " + text);
        }
    }

    public static void main(String[] args) {
        int loggerLevel = 1; // INFO: the cheap exit check
        List<Handler> chain = List.of(new Handler("console", 1), new Handler("file", 3));
        int[] lv = {0, 1, 3};
        String[] tx = {"cache miss", "server started", "disk full"};
        for (int i = 0; i < 3; i++) {
            System.out.println(LEVELS[lv[i]] + " " + tx[i]);
            if (lv[i] < loggerLevel) { System.out.println("  dropped by logger level"); continue; }
            for (Handler h : chain) h.handle(lv[i], tx[i]);
        }
    }
}

