import java.util.*;

public class Main {
    public static void main(String[] args) {
        int capacity = 3;
        Deque<String> queue = new ArrayDeque<>(); // bounded queue between request threads and writer
        int dropped = 0;
        String[] levels = {"INFO", "INFO", "INFO", "INFO", "INFO", "ERROR"};
        String[] texts = {"a", "b", "c", "d", "e", "f"};
        for (int i = 0; i < 6; i++) {
            if (queue.size() < capacity) {
                queue.addLast(texts[i]);
            } else if (levels[i].equals("ERROR")) {
                queue.removeFirst(); dropped++; // policy: ERROR displaces the oldest entry
                queue.addLast(texts[i]);
            } else {
                dropped++; // policy: drop non-errors when full, and count them
            }
        }
        System.out.println("queued: " + queue + " dropped: " + dropped);
        List<String> batch = new ArrayList<>(queue); // writer drains in a batch
        queue.clear();
        System.out.println("writer wrote batch: " + batch);
    }
}

