public class Main {
    public static void main(String[] args) {
        int parts = 3;
        List<List<String>> log = new ArrayList<>(); // each partition = append-only list
        for (int i = 0; i < parts; i++) log.add(new ArrayList<>());
        String[] keys = {"o1", "o2", "o3", "o1", "o2", "o1"};
        for (int i = 0; i < keys.length; i++) {
            int h = 0;
            for (char c : keys[i].toCharArray()) h += c;
            int p = h % parts; // partitioner: same key -> same partition
            log.get(p).add(keys[i] + "#" + i);
            System.out.println("send " + keys[i] + " -> partition " + p + " offset " + (log.get(p).size() - 1));
        }
        // Reading never deletes: a group resumes from its committed offset, another group replays
        int committed = 1;
        System.out.println("group A reads p1 from offset " + committed + ": " + log.get(1).subList(committed, log.get(1).size()));
        System.out.println("group B replays p1 from 0: " + log.get(1));
    }
}

