import java.util.*;

public class Main {
    static List<Integer> run(boolean commitFirst, boolean dedupe) {
        List<Integer> processed = new ArrayList<>();
        Set<Integer> seen = new HashSet<>();
        int committed = 0; boolean crashed = false;
        while (committed < 5) {                 // each pass = one consumer life
            int pos = committed;
            while (pos < 5) {
                int msg = pos + 1;
                if (commitFirst) committed = msg;  // commit BEFORE processing
                boolean crash = msg == 3 && !crashed;
                if (crash && commitFirst) { crashed = true; break; }
                if (!dedupe || seen.add(msg)) processed.add(msg);
                if (crash) { crashed = true; break; }  // crash AFTER processing, before commit
                if (!commitFirst) committed = msg;
                pos = msg;
            }
        }
        return processed;
    }

    public static void main(String[] args) {
        System.out.println("at-most-once (commit first):    " + run(true, false));
        System.out.println("at-least-once (process first):  " + run(false, false));
        System.out.println("at-least-once + dedupe by id:   " + run(false, true));
    }
}

