public class Main {
    public static void main(String[] args) {
        int parts = 3, consumers = 2;
        String[][] events = {{"o1", "created"}, {"o2", "created"}, {"o1", "paid"},
                             {"o2", "paid"}, {"o1", "shipped"}, {"o3", "created"}};
        List<List<String>> log = new ArrayList<>();
        for (int i = 0; i < parts; i++) log.add(new ArrayList<>());
        for (String[] e : events) {
            int h = 0;
            for (char c : e[0].toCharArray()) h += c;
            log.get(h % parts).add(e[0] + ":" + e[1]); // same key -> same partition, in send order
        }
        // each partition has exactly ONE owner in the group; here owner = partition % consumers
        for (int c = 0; c < consumers; c++) {
            System.out.println("consumer " + c);
            for (int p = 0; p < parts; p++)
                if (p % consumers == c) System.out.println("  p" + p + ": " + log.get(p));
        }
    }
}

