public class Main {
    static Map<String, String> data = new HashMap<>();
    static Deque<Map<String, String>> undo = new ArrayDeque<>(); // one undo map per open transaction

    static void set(String k, String v) {
        if (!undo.isEmpty() && !undo.peek().containsKey(k))
            undo.peek().put(k, data.get(k)); // old value; null = key was absent (tombstone)
        data.put(k, v);
    }
    static void rollback() {
        for (Map.Entry<String, String> e : undo.pop().entrySet()) {
            if (e.getValue() == null) data.remove(e.getKey()); else data.put(e.getKey(), e.getValue());
        }
    }
    static void commit() {
        Map<String, String> top = undo.pop();
        if (!undo.isEmpty()) for (Map.Entry<String, String> e : top.entrySet())
            undo.peek().putIfAbsent(e.getKey(), e.getValue()); // parent keeps ITS older value
    }
    static void show() { System.out.println("a=" + data.get("a") + " b=" + data.get("b")); }

    public static void main(String[] args) {
        set("a", "1");
        undo.push(new HashMap<>()); set("a", "2");   // BEGIN, SET a 2
        undo.push(new HashMap<>()); set("a", "3"); set("b", "5"); // BEGIN, SET a 3, SET b 5
        commit(); show();   // inner commit merges into the parent
        rollback(); show(); // outer rollback undoes both layers
    }
