using System;
using System.Collections.Generic;

class Program
{
    static long now = 0; // injected clock: tests move time instantly
    static Dictionary<string, string> val = new Dictionary<string, string>();
    static Dictionary<string, long> expireAt = new Dictionary<string, long>(); // absolute expiry time

    static void Put(string k, string v, long ttl)
    {
        val[k] = v;
        if (ttl > 0) expireAt[k] = now + ttl; else expireAt.Remove(k);
    }
    // Lazy expiry: check on every access, delete if due
    static string Get(string k)
    {
        long e;
        if (expireAt.TryGetValue(k, out e) && now >= e) { val.Remove(k); expireAt.Remove(k); }
        string v;
        return val.TryGetValue(k, out v) ? v : "null";
    }
    static long Ttl(string k)
    {
        if (Get(k) == "null") return -2;   // missing
        long e;
        return expireAt.TryGetValue(k, out e) ? e - now : -1; // -1 = no expiry
    }

    static void Main()
    {
        Put("a", "x", 10); Put("b", "y", 0);
        now = 5;
        Console.WriteLine("t=5  get a=" + Get("a") + " ttl a=" + Ttl("a") + " ttl b=" + Ttl("b"));
        now = 10;
        Console.WriteLine("t=10 get a=" + Get("a") + " ttl a=" + Ttl("a") + " size=" + val.Count);
    }
}
